package net.rec0de.android.watchwitch.servicehandlers

import net.rec0de.android.watchwitch.Log
import net.rec0de.android.watchwitch.WatchState
import net.rec0de.android.watchwitch.alloy.AlloyHandler
import net.rec0de.android.watchwitch.alloy.AlloyMessage
import net.rec0de.android.watchwitch.alloy.AlloyService
import net.rec0de.android.watchwitch.alloy.ProtobufMessage
import net.rec0de.android.watchwitch.bitmage.fromHex
import net.rec0de.android.watchwitch.bitmage.hex
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoBuf
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoI64
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoString
import net.rec0de.android.watchwitch.decoders.protobuf.ProtoVarInt
import net.rec0de.android.watchwitch.decoders.protobuf.ProtobufParser
import net.rec0de.android.watchwitch.devices.Watch
import net.rec0de.android.watchwitch.toAppleTimestamp
import java.util.Date

object BluetoothRegistry : AlloyService {

    private const val TOPIC = "com.apple.private.alloy.bluetoothregistry"
    private const val TOPIC_CLASSC = "com.apple.private.alloy.bluetoothregistryclassc"
    override val handlesTopics = listOf(TOPIC, TOPIC_CLASSC)
    override fun acceptsMessageType(msg: AlloyMessage) = msg is ProtobufMessage
    override fun acceptsLocalDeviceRole(device: AlloyService.Device) = device == AlloyService.Device.WATCH
    private const val TAG = "BluetoothRegistry"

    override fun receiveMessage(msg: AlloyMessage, handler: AlloyHandler) {
        msg as ProtobufMessage

        val decoded = try {
            val decoded = ProtobufParser().parse(msg.payload)
            Log.d(TAG, "got message type ${msg.type}: $decoded")
            decoded
        }
        catch (e: Exception) {
            Log.d(TAG, "expected Protobuf payload, got ${msg.payload.hex()}")
            return
        }

        when(msg.topic) {
            TOPIC -> handleRegular(msg.type, decoded, handler)
            TOPIC_CLASSC -> handleClassC(decoded, handler)
        }
    }

    private fun handleRegular(type: Int, decoded: ProtoBuf, handler: AlloyHandler) {
        if(type != 3)
            return

        val requestType = (decoded.objs[1]!!.first() as ProtoVarInt).value.toInt()

        when(requestType) {
            1 -> {
                Log.d(TAG, "is request for locale? replying")
                val reply = ProtoBuf(mapOf(
                    1 to listOf(ProtoVarInt(0)),
                    2 to listOf(
                        ProtoBuf.singles(mapOf(
                            1 to ProtoString("currentUserLocale"),
                            2 to ProtoBuf.singles(mapOf(1 to ProtoString("en_DE")))
                        )),
                        ProtoBuf.singles(mapOf(
                            1 to ProtoString("preferredUserLocale"),
                            2 to ProtoBuf(mapOf(
                                7 to listOf(
                                    ProtoBuf.singles(mapOf(1 to ProtoString("en-DE"))),
                                    ProtoBuf.singles(mapOf(1 to ProtoString("de-DE")))
                                )
                            ))
                        ))
                    ),
                    3 to listOf(ProtoI64(Date().toAppleTimestamp()))
                ))

                send(reply.renderStandalone(), 2, handler, classC = false)
            }
            3 -> {
                Log.d(TAG, "is request for name? replying")
                val reply = ProtoBuf.singles(mapOf(
                    1 to ProtoVarInt(0),
                    2 to ProtoBuf.singles(mapOf(
                        1 to ProtoString("name"),
                        2 to ProtoBuf.singles(mapOf(1 to ProtoString(Watch.NAME)))
                    )
                    ),
                    3 to ProtoI64(Date().toAppleTimestamp())
                ))

                send(reply.renderStandalone(), 2, handler, classC = false)
            }
        }
    }

    private fun handleClassC(decoded: ProtoBuf, handler: AlloyHandler) {
        val requestType = (decoded.objs[1]!!.first() as ProtoVarInt).value.toInt()

        when(requestType) {
            1 -> {
                Log.d(TAG, "is device info")
                val payload = decoded.objs[2]!!
                val imei = payload.firstOrNull() {
                    it is ProtoBuf && it.objs[1]?.first() is ProtoString && (it.objs[1]!!.first() as ProtoString).stringValue == "IMEI"
                }

                if (imei != null) {
                    val imeiValue = ((imei as ProtoBuf).objs[2]!!.first() as ProtoBuf).objs[1]!!.first()
                    val imeiString = (imeiValue as ProtoString).stringValue
                    WatchState.addStolenInfo("IMEI: $imeiString")
                }

                // send prerecorded reply
                // (this has a static, outdated timestamp, but we hope the phone doesn't care)
                //val reply = "".fromHex()
                val reply = "0800".fromHex()
                send(reply, 2, handler, classC = true)
            }
        }
    }

    private fun send(data: ByteArray, type: Int, handler: AlloyHandler, classC: Boolean) {
        Log.d(TAG, "sending data: ${data.hex()} type $type")
        val topic = if(classC) TOPIC_CLASSC else TOPIC
        handler.sendProtobuf(data, topic, type, false)
    }

}